def chunk_overlap(text: str, max_len: int, overlap: int) -> list:
    if not text or max_len <= 0:
        return []

    step = max_len - overlap
    if step <= 0:
        step = 1

    chunks = []
    start = 0
    text_len = len(text)

    while start < text_len:
        chunks.append(text[start:start + max_len])
        start += step

    return chunks

def chunk_overlap(text: str, max_len: int, overlap: int) -> list:
    if not text or max_len <= 0:
        return []

    step = max_len - overlap
    if step <= 0:
        return []

    result = []
    start = 0
    n = len(text)

    while start < n:
        end = start + max_len
        if end > n:
            end = n
        result.append(text[start:end])

        if end == n:
            break

        start += step

    return result

